t.script:
document.addEventListener('DOMContentLoaded', function() {
    const form = document.getElementById('invitation-form');
    const submitBtn = document.getElementById('submit-btn');
    const errorDiv = document.getElementById('error-message');
    const successDiv = document.getElementById('success-message');
    const passwordInput = document.getElementById('password');
    const confirmInput = document.getElementById('password-confirm');

    // Validation custom pour les mots de passe
    confirmInput.addEventListener('input', function() {
        if (passwordInput.value !== confirmInput.value) {
            confirmInput.setCustomValidity('Les mots de passe ne correspondent pas');
        } else {
            confirmInput.setCustomValidity('');
        }
    });

    form.addEventListener('submit', async function(e) {
        e.preventDefault();
        e.stopPropagation();

        // Validation Bootstrap
        if (!form.checkValidity()) {
            form.classList.add('was-validated');
            return;
        }

        const token = document.getElementById('invitation-token').value;
        const fullName = document.getElementById('full-name').value;
        const password = passwordInput.value;
        const passwordConfirm = confirmInput.value;

        // Vérifier que les mots de passe correspondent
        if (password !== passwordConfirm) {
            errorDiv.textContent = 'Les mots de passe ne correspondent pas';
            errorDiv.style.display = 'block';
            successDiv.style.display = 'none';
            return;
        }

        // Désactiver le bouton et afficher un loader
        submitBtn.disabled = true;
        submitBtn.innerHTML = 'Activation en cours...';
        errorDiv.style.display = 'none';
        successDiv.style.display = 'none';

        try {
            // Appeler l'API d'acceptation d'invitation
            const response = await fetch('/onedesk/invite/accept/submit', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        token: token,
                        name: fullName,
                        password: password
                    }
                })
            });

            const result = await response.json();

            if (result.error) {
                throw new Error(result.error.data.message || result.error.message);
            }

            const data = result.result;

            if (data.status === 'success') {
                successDiv.textContent = data.message;
                successDiv.style.display = 'block';

                // Rediriger vers la page de connexion après 2 secondes
                setTimeout(function() {
                    window.location.href = '/web/login';
                }, 2000);
            } else {
                throw new Error(data.message || 'Erreur lors de l\'activation du compte');
            }
        } catch (error) {
            console.error('Error:', error);
            errorDiv.textContent = error.message || 'Une erreur est survenue. Veuillez réessayer.';
            errorDiv.style.display = 'block';
            submitBtn.disabled = false;
            submitBtn.innerHTML = 'Activer mon compte';
        }
    });
});
